contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Prepare reserves/targets so that _RState_ == BELOW_ONE and _BASE_RESERVE_ == _BASE_TARGET_.
    // We drive this by calling buyShares to initialize state when totalSupply == 0, then manipulate storage via available external functions.
    // We use parameters to set amounts used in calls; minimal calls: buyShares to initialize, then sync to ensure reserves reflect token balances, then call correctRState and observe R state.

    function runTest(address to, uint256 priceI) external {
        // Preconditions: owner (msg.sender) must be maintainer and tokens must be set up in c externally by test harness.
        // We only call sequence of external functions on c as required.

        // 1) adjustPrice to set _I_ to a chosen value (onlyMaintainer required in real use; test harness must ensure msg.sender==_MAINTAINER_ when calling this contract)
        // This call may revert if caller isn't maintainer; caller of runTest must be maintainer of c in harness.
        c.adjustPrice(priceI);

        // 2) Call getPMMStateForCall to read R and reserves/targets before correction
        ( , , uint256 B, , uint256 B0, , uint256 Rbefore) = c.getPMMStateForCall();

        // 3) Call correctRState which is the function under test (state-changing top-level call)
        c.correctRState();

        // 4) Read R after
        ( , , , , , , uint256 Rafter) = c.getPMMStateForCall();

        // Assert: if before R indicated BELOW_ONE (value 2) and B == B0 then Rafter must still equal Rbefore.
        // On the original contract this holds (no change when equal). The mutant with <= will change R to ONE (value 0), violating the assert.
        if (Rbefore == uint256(PMMPricing.RState.BELOW_ONE)) {
            require(B == B0, "precondition reserves not equal");
        }
        assert(!(Rbefore == uint256(PMMPricing.RState.BELOW_ONE) && B == B0 && Rafter != Rbefore));
    }

    // Allow receiving ETH if needed by harness
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, IERC20 baseToken, IERC20 quoteToken, uint256 baseFund, uint256 quoteFund) public payable {
        // Precondition: ensure starting fresh state where totalSupply == 0 and this contract can fund tokens
        require(c.totalSupply() == 0, "NEEDS_INITIAL_TOTALSUPPLY_ZERO");
        // Caller must have tokens; we assume test environment will transfer tokens to this contract beforehand
        // Approve tokens to c by calling token contracts (these are external to c). However we may not call external token approve here
        // Instead rely on test harness to have transferred tokens directly into c before calling run.
        // Call buyShares, which will set initial targets when totalSupply == 0
        c.buyShares(to);
        // Observe: vault reserves and PMM state's B0 (BASE_TARGET)
        (uint256 baseReserve, ) = c.getVaultReserve();
        (, , uint256 B, , uint256 B0, , ) = c.getPMMStateForCall();
        // For the original contract, at initial buyShares the recorded BASE_TARGET (B0) equals the on-chain base reserve; mutant may make B0 > baseReserve
        assert(B0 == baseReserve);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 baseDeposit, uint256 quoteDeposit) public payable {
        // we need to supply tokens to the vault before calling buyShares; require caller has sent enough ETH if tokens are ETH-like
        // Precondition: caller must provide positive base input so buyShares proceeds and ensure initial totalSupply == 0
        // The test assumes c.totalSupply() == 0 initially (caller of test must deploy in that state)
        require(baseDeposit > 0, "need base deposit");
        // Call buyShares with arbitrary 'to' (use address(this)) — function is external and will read token balances from c; we only pass through parameters.
        // This test relies on the environment already having set up token balances for c such that baseDeposit and quoteDeposit are reflected
        c.buyShares(address(this));
        // After buyShares when totalSupply was zero, original ensures base target <= base reserve. We read through public getters:
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();
        // Assert general invariant: base target (B0) is not greater than base reserve (B)
        assert(B0 <= B);
    }
    receive() external payable { }
}

